source('R/stile.R')
d<-leggi('fossili_simulati.csv');d$morfotipo<-factor(d$morfotipo)
x<-d$diametro_tot_um
verifica('160 fossili, 80 per gruppo',nrow(d)==160 && all(table(d$morfotipo)==80))
v<-data.frame(livello=factor(c('L1','L2','Totale'),levels=c('L1','L2','Totale')),p=c(.8,.6,.62))
salva('M03','F01',ggplot(v,aes(livello,p,fill=livello))+geom_col(width=.65)+scale_fill_manual(values=geo[1:3],guide='none')+scale_y_continuous(labels=function(z)paste0(100*z,'%'),limits=c(0,1))+labs(x=NULL,y='Proporzione Spiky'))
z<-data.frame(M=seq(5,100),Media=(12+seq(5,100))/4,Mediana=4.5)
zz<-rbind(data.frame(M=z$M,y=z$Media,Sintesi='Media'),data.frame(M=z$M,y=z$Mediana,Sintesi='Mediana'))
salva('M03','F02',ggplot(zz,aes(M,y,colour=Sintesi))+geom_line(linewidth=1.2)+scale_colour_manual(values=geo[1:2])+labs(x='Quarto valore',y='Sintesi'))
# Istogrammi calcolati esplicitamente: stessa origine delle classi.
histo<-function(v,bw,label) {br<-seq(floor(min(v)),ceiling(max(v))+bw,by=bw);h<-hist(v,breaks=br,plot=FALSE);data.frame(x=h$mids,n=h$counts,bw=bw,classe=label)}
h<-rbind(histo(x,.5,'Ampiezza 0,5 µm'),histo(x,1,'Ampiezza 1 µm'))
salva('M03','F03',ggplot(h,aes(x,n))+geom_rect(aes(xmin=x-bw/2,xmax=x+bw/2,ymin=0,ymax=n),fill=geo[1],colour=paper)+facet_wrap(~classe,ncol=1)+scale_y_continuous(breaks=c(0,30,60))+labs(x='Diametro (µm)',y='Conteggio'),h=3.8)
den<-function(v,g) {k<-density(v,bw=.4);data.frame(x=k$x,y=k$y,Gruppo=g)}
dd<-do.call(rbind,c(lapply(levels(d$morfotipo),function(g)den(x[d$morfotipo==g],g)),list(den(x,'Totale'))))
salva('M03','F04',ggplot(dd,aes(x,y,colour=Gruppo))+geom_line(linewidth=1.1)+scale_colour_manual(values=geo[1:3])+labs(x='Diametro (µm)',y='Densità (µm⁻¹)'))
salva('M03','F05',ggplot(d,aes(diametro_tot_um,colour=morfotipo))+stat_ecdf(linewidth=1.1)+scale_colour_manual(values=geo[1:2])+labs(x='Diametro (µm)',y='Quota cumulata'))
salva('M03','F06',ggplot(d,aes(morfotipo,diametro_tot_um,colour=morfotipo))+geom_boxplot(outlier.shape=NA,width=.45)+geom_point(position=position_jitter(width=.12,height=0,seed=303),alpha=.55,size=1.5)+scale_colour_manual(values=geo[1:2],guide='none')+labs(x=NULL,y='Diametro (µm)'))
salva('M03','F07',ggplot(d,aes(diametro_tot_um,fill=morfotipo))+geom_histogram(binwidth=.5,boundary=0,colour=paper)+facet_wrap(~morfotipo,ncol=1)+scale_y_continuous(breaks=c(0,10,20))+scale_fill_manual(values=geo[1:2],guide='none')+labs(x='Diametro (µm)',y='Conteggio'),h=3.8)
salva('M03','F08',ggplot(d,aes(diametro_tot_um,diaframma_um,colour=morfotipo))+geom_point(size=1.7,alpha=.8)+scale_colour_manual(values=geo[1:2])+labs(x='Diametro totale (µm)',y='Diaframma (µm)'))
set.seed(309);u<-seq(-2,2,length.out=70)
q<-rbind(data.frame(x=u,y=u+rnorm(70,0,.3),Forma='Lineare'),data.frame(x=u,y=u^2+rnorm(70,0,.2),Forma='A U'),data.frame(x=u,y=rnorm(70),Forma='Indipendenti'))
salva('M03','F09',ggplot(q[q$Forma=='A U',],aes(x,y))+geom_point(colour=geo[2],size=1.8)+labs(x='x',y='y'))
set.seed(310);q<-data.frame(E=runif(60,0,100),N=rnorm(60,50,6))
salva('M03','F10',ggplot(q,aes(E,N))+geom_hline(yintercept=50,colour=geo[3],linewidth=1)+geom_point(colour=geo[1],size=2)+coord_fixed(xlim=c(0,100),ylim=c(0,100))+labs(x='Est (m)',y='Nord (m)'))
q<-data.frame(x=c(1,2,5,10,20,50,100),i=1)
salva('M03','F11',ggplot(q,aes(x,i))+geom_point(colour=geo[1],size=3)+scale_x_log10(breaks=c(1,10,100))+scale_y_continuous(NULL,breaks=NULL)+labs(x='Dimensione (µm)')+coord_cartesian(ylim=c(.5,1.5)))
verifica('aggregazione pesata',(8+54)/(10+90)==.62)
verifica('sintesi estremo',mean(c(3,4,5,100))==28 && median(c(3,4,5,100))==4.5)
verifica('deviazioni standard',sd(c(4,5,6))==1 && sd(c(0,5,10))==5)
verifica('ecdf agli estremi',ecdf(x)(max(x))==1 && ecdf(x)(min(x)-1)==0)
